        // Since N can be up to 10^9, X will be around 4*N/3 or so.
        // We can use binary search.

        long low = 1;
        long high = 4 * N + 10; // safe upper bound

        while (low < high) {
            long mid = (low + high) / 2;
            if (countSuitable(mid) >= N) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }

        System.out.println(low);
    }

    static long countSuitable(long X) {
        if (X < 1) return 0;
        long unsuitable = 0;
        if (X >= 1) unsuitable += 1; // for 1
        if (X >= 4) unsuitable += 1; // for 4
        if (X >= 2) {
            unsuitable += (X + 2) / 4; // for 2, 6, 10, ...
        }
        return X - unsuitable;
    }
}
